#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main() {
    int n, k, m;
    cin >> n >> k >> m;

    auto fastExponentiation = [&](int base, int exp) {
        int result = 1;
        while (exp > 0) {
            if (exp & 1) result = (long long)result * base % m;
            base = (long long)base * base % m;
            exp >>= 1;
        }
        return result;
    };

    if (n % 2 == 1) {
        cout << fastExponentiation(k, n) << "\n";
    } else {
        vector<long long> factorial(n + 1, 1), inv_factorial(n + 1, 1);
        for (int i = 1; i <= n; ++i) {
            factorial[i] = factorial[i - 1] * i % m;
        }
        inv_factorial[n] = fastExponentiation(factorial[n], m - 2);
        for (int i = n - 1; i >= 0; --i) {
            inv_factorial[i] = inv_factorial[i + 1] * (i + 1) % m;
        }

        vector<int> positions;
        for (int i = 0; i < n; ++i) {
            if (n & (1 << i))
                positions.push_back(i);
        }

        vector<int> segment_sizes(n + 1, 0);
        for (int i = 0; i <= n; ++i) {
            int j = i;
            while (j != 0) {
                segment_sizes[i]++;
                j = (j - 1) & j;
            }
        }

        vector<bool> visited_mask(1 << n, false);
        for (int mask = (1 << n) - 1; mask >= 0; --mask) {
            if (mask == 0) break;
            visited_mask[mask] = true;
        }

        vector<vector<long long>> dp(n + 1, vector<long long>(1 << n, 0));
        dp[0][0] = 1;

        for (int mask = 0; mask < (1 << n); ++mask) {
            for (int s = 0; s <= n; ++s) {
                if (dp[s][mask] == 0) continue;
                for (int sub_mask = mask; sub_mask; sub_mask = (sub_mask - 1) & mask) {
                    int l = min(k, segment_sizes[mask ^ sub_mask] + 1);
                    for (int s2 = 1; s2 <= l; ++s2) {
                        if (dp[s - 1][mask ^ sub_mask]) {
                            dp[s][mask] = (dp[s][mask] + dp[s - 1][mask ^ sub_mask] * inv_factorial[sub_mask]) % m;
                        }
                    }
                }
            }
        }

        long long total = 0;
        int full_mask = (1 << n) - 1;
        for (int i = 0; i <= min(k, segment_sizes[n]); ++i) {
            if (dp[i][full_mask]) {
                long long val = dp[i][full_mask] * factorial[k] % m;
                val = val * inv_factorial[k - i] % m;
                val = val * inv_factorial[i] % m;
                val = val * factorial[n] % m;
                total = (total + val) % m;
            }
        }
        cout << (fastExponentiation(k, n) - total + m) % m << "\n";
    }
    return 0;
}
